import java.nio.file.*;import java.time.*;import java.util.*;import com.kingofcards.crm.ops.fenced.*;
/** Uses a verifier copy with ONLY the private-directory literal redirected to this fixture. */
class FencedStartVerifierTest {
 static Path root,archive;static String manifest;static int count;static final String GUARD="fixture-guard";
 static void write(Properties p,Path path)throws Exception{try(var out=Files.newOutputStream(path)){p.store(out,"Isolated fixture only");}}
 static Properties cert(){var p=new Properties();p.setProperty("purpose","READ_ONLY_FENCED_HANDOVER");p.setProperty("historicalOperationId",FencedPolicy.OP);p.setProperty("historicalState","UNKNOWN");p.setProperty("archiveManifestSha256",manifest);p.setProperty("afterStartAdmission","READS_ONLY");p.setProperty("rollbackAdmission","READS_ONLY");p.setProperty("releaseWrites","false");p.setProperty("timestamp",Instant.now().toString());return p;}
 static void attempt(String role,Properties c,boolean pass,boolean badStop,boolean badBootstrap)throws Exception{
  Path file=root.resolve("certificate-"+count+".properties");write(c,file);String sha=FencedPolicy.hash(file);var stop=new Properties();stop.setProperty("certificateSha256",badStop?"wrong":sha);stop.setProperty("archiveManifestSha256",manifest);stop.setProperty("guardSha256",GUARD);write(stop,root.resolve("fenced-stop-attempt-3160.properties"));var start=new Properties();start.setProperty("appHash",FencedPolicy.NEW);start.setProperty("bootstrapHash",badBootstrap?"wrong":FencedPolicy.BARRIER);start.setProperty("archiveManifestSha256",manifest);write(start,root.resolve("fenced-Updated-start.properties"));
  try{VerifyFencedStartFixture.main(new String[]{role,file.toString(),sha,archive.toString(),manifest,GUARD});if(!pass)throw new AssertionError("Unsafe start accepted");}catch(IllegalStateException e){if(pass)throw e;}count++;
 }
 public static void main(String[]a)throws Exception{
  root=Path.of(a[0]).toRealPath();archive=Files.createDirectory(root.resolve("archive"));var unknown=new Properties();unknown.setProperty("operationId",FencedPolicy.OP);unknown.setProperty("state","UNKNOWN");unknown.setProperty("neverReplay","true");unknown.setProperty("neverDiscard","true");unknown.setProperty("originalBindingRecovered","false");write(unknown,archive.resolve("historical-unknown.properties"));Files.writeString(archive.resolve("evidence.txt"),"Preserved UNKNOWN fixture");Files.writeString(archive.resolve("plan.txt"),"Read-only fixture");var m=new Properties();m.setProperty("fileCount","3");int i=0;for(String name:List.of("historical-unknown.properties","evidence.txt","plan.txt")){m.setProperty("file."+i+".path",name);m.setProperty("file."+i+".sha256",FencedPolicy.hash(archive.resolve(name)));i++;}write(m,archive.resolve("manifest.properties"));manifest=FencedPolicy.hash(archive.resolve("manifest.properties"));String original=FencedPolicy.hash(archive.resolve("historical-unknown.properties"));
  attempt("Updated",cert(),true,false,false);attempt("Rollback",cert(),true,false,false);
  for(var e:Map.of("purpose","PREPARATION_ONLY","historicalState","COMMITTED","historicalOperationId","00000000-0000-4000-8000-000000000000","afterStartAdmission","OPEN","rollbackAdmission","OPEN","releaseWrites","true").entrySet()){var c=cert();c.setProperty(e.getKey(),e.getValue());attempt("Updated",c,false,false,false);}
  attempt("Updated",cert(),false,true,false);attempt("Rollback",cert(),false,false,true);var expired=cert();expired.setProperty("timestamp",Instant.now().minusSeconds(301).toString());attempt("Updated",expired,false,false,false);expired=cert();expired.setProperty("timestamp",Instant.now().minusSeconds(1801).toString());attempt("Rollback",expired,false,false,false);
  if(!original.equals(FencedPolicy.hash(archive.resolve("historical-unknown.properties"))))throw new AssertionError("UNKNOWN discarded");System.out.println("PASS "+count+" start/recovery verifier cases; only fixture directory redirected; no process, network or database calls");
 }
}
